const PROMOS=[{id:"regalo-iphone-17-18",activa:!0,prioridad:1,inicio:"2026-11-02T00:00:00-03:00",fin:null,titulo:"Cargador, funda y vidrio templado de regalo",texto:"Por la compra de un iPhone 17 o un iPhone 18.",regalos:["Cargador","Funda","Vidrio templado"],etiqueta:"Regalo: cargador, funda y vidrio",etiquetaCorta:"Con regalos",aplicaA:{categoria:"iPhone",prefijosNombre:["iPhone 17","iPhone 18"],condicion:null},condiciones:"",cta:{texto:"Aprovechar por WhatsApp",mensaje:"Hola Tecnolab, quiero aprovechar la promo: cargador, funda y vidrio templado de regalo por la compra de un iPhone 17 o 18."},popup:{mostrar:!0,retrasoSeg:8,frecuenciaHoras:24,paginas:["index","catalogo"]}}];function promoVigente(i){const o=(i instanceof Date?i:new Date(i||Date.now())).getTime();return PROMOS.map((e,a)=>({p:e,i:a})).filter(({p:e})=>e.activa===!0&&Number.isFinite(Date.parse(e.inicio))&&Date.parse(e.inicio)<=o&&(!e.fin||Number.isFinite(Date.parse(e.fin))&&o<=Date.parse(e.fin))).sort((e,a)=>(e.p.prioridad??100)-(a.p.prioridad??100)||e.i-a.i).map(({p:e})=>e)}function promoAplica(i,o){const e=i.aplicaA||{};if(e.categoria&&o.categoria!==e.categoria||e.condicion&&(o.condicion||"nuevo")!==e.condicion)return!1;const a=e.prefijosNombre||[];return!a.length||a.some(n=>o.nombre===n||String(o.nombre).startsWith(n+" "))}function promosDe(i,o){return promoVigente(o).filter(e=>promoAplica(e,i))}function fechaLegible(i){const o=new Date(i);if(!Number.isFinite(o.getTime()))return"";const e={timeZone:"America/Argentina/Mendoza"},a=new Intl.DateTimeFormat("es-AR",{...e,year:"numeric"}).format(o)!==new Intl.DateTimeFormat("es-AR",{...e,year:"numeric"}).format(new Date);return new Intl.DateTimeFormat("es-AR",{...e,day:"numeric",month:"long",...a?{year:"numeric"}:{}}).format(o)}function listaRegalos(i){const o=(i||[]).map(e=>String(e).toLowerCase());return o.length>1?o.slice(0,-1).join(", ")+" y "+o[o.length-1]:o.join("")}
